        public static int __hash32(long h) => unchecked((int)(h ^ (h >> 32)));
        public static int __hash32(int h) => h;
        public static int __hash32(object? h) => h is long l ? __hash32(l) : h is int i ? i : h?.GetHashCode() ?? 0;

