        public static string __repeat(string s, long n) => n <= 0 || s.Length == 0 ? "" : new StringBuilder(checked(s.Length * (int)n)).Insert(0, s, (int)n).ToString();
        public static string __repeat(long n, string s) => __repeat(s, n);
        public static List<T> __repeat<T>(List<T> l, long n)
        {
            int count = n <= 0 ? 0 : checked((int)n);
            if (l.Count == 1 && count > 0)
            {
                // [x] * n — the common "preallocate" idiom
                var filled = new List<T>(count);
                System.Runtime.InteropServices.CollectionsMarshal.SetCount(filled, count);
                System.Runtime.InteropServices.CollectionsMarshal.AsSpan(filled).Fill(l[0]);
                return filled;
            }
            var r = new List<T>(checked(l.Count * count));
            for (int i = 0; i < count; i++) r.AddRange(l);
            return r;
        }
        public static List<T> __repeat<T>(long n, List<T> l) => __repeat(l, n);
        /// <summary>a * b with late-bound operands: sequence repetition when one side is a str, list or tuple.</summary>
        public static dynamic mul(dynamic a, dynamic b)
        {
            object oa = a, ob = b;
            if (TryClassBinaryOp(oa, ob, "mul", "*", out var result)) return result!;
            oa = NumericOperand(oa)!;
            ob = NumericOperand(ob)!;
            PromoteMixedFloat(ref oa, ref ob);
            if (oa is string s1 && TryRepeatCount(ob, out var n1)) return __repeat(s1, n1);
            if (ob is string s2 && TryRepeatCount(oa, out var n2)) return __repeat(s2, n2);
            if (oa is IList l1 && TryRepeatCount(ob, out var n3)) return RepeatList(l1, n3);
            if (ob is IList l2 && TryRepeatCount(oa, out var n4)) return RepeatList(l2, n4);
            if (oa is ITuple && TryRepeatCount(ob, out var tupleCount)) return __tuprep<object?>(oa, tupleCount);
            if (ob is ITuple && TryRepeatCount(oa, out var swappedCount)) return __tuprep<object?>(ob, swappedCount);
            if (AsInt(oa, out var x) && AsInt(ob, out var y)) return checked(x * y);
            return checked((dynamic)oa * (dynamic)ob);
        }

        static void PromoteMixedFloat(ref object left, ref object right)
        {
            if (left is BigInteger && right is double or float) left = RealToDouble(left);
            else if (right is BigInteger && left is double or float) right = RealToDouble(right);
        }

        static bool TryRepeatCount(object? value, out long count)
        {
            if (value is BigInteger integer)
            {
                count = checked((long)integer);
                return true;
            }
            return AsInt(value, out count);
        }

        /// <summary>a + b with late-bound operands: list concatenation (str and numbers bind normally).</summary>
        public static dynamic add(dynamic a, dynamic b)
        {
            object left = a, right = b;
            if (TryClassBinaryOp(left, right, "add", "+", out var result,
                allowSequenceFallback: left is ITuple && right is PyTupleSubclass)) return result!;
            left = NumericOperand(left)!;
            right = NumericOperand(right)!;
            PromoteMixedFloat(ref left, ref right);
            a = left;
            b = right;
            if (a is ITuple && b is ITuple) return __tupcat<object?>((object)a, (object)b);
            if (a is IList la && b is IList lb && !(a is string) && !(a is IDictionary))
            {
                if (la.GetType() != lb.GetType() || la.IsFixedSize) return __concat_any(la, lb);
                var r = (IList)Activator.CreateInstance(la.GetType())!;
                foreach (var x in la) r.Add(x);
                foreach (var x in lb) r.Add(x);
                return r;
            }
            if (AsInt((object)a, out var ia) && AsInt((object)b, out var ib)) return checked(ia + ib);
            return checked(a + b);
        }

        static IList RepeatList(IList l, long n)
        {
            var r = (IList)Activator.CreateInstance(l.GetType())!;
            for (long i = 0; i < n; i++) foreach (var x in l) r.Add(x);
            return r;
        }

